function rebalancePcts(){
 let out={...state.pct}; if(!state.autoRebalance)return out;
 let unspent={}; let total=0;
 for(const r of 'PDCA'){unspent[r]=Math.max(0,baseBudget(r)-(state.spent[r]||0));total+=unspent[r]}
 if(total<=0)return out;
 // These are RESIDUAL percentages of the money still available, not percentages of the original 500.
 for(const r of 'PDCA')out[r]=unspent[r]/total*100;
 return out;
}
function residualRoleBudget(r){
 if(!state.autoRebalance)return Math.max(0,baseBudget(r)-(state.spent[r]||0));
 const p=rebalancePcts()[r]||0; return Math.max(0,creditsLeft()*p/100);
}
function reserveForFuture(){return 0}
function futureMinimumExcluding(r){return 0}
function roleRemainingBudget(r){return residualRoleBudget(r)}
function targetPenalty(p){
 let score=0;
 if(!p.target)return score;
 const pr=(p.priority||'').toUpperCase(); if(pr.includes('ASSOLUTO'))score+=18; else if(pr.includes('TOP'))score+=12; else if(pr.includes('QUASI'))score+=9; else if(pr.includes('PIANO'))score+=8; else if(pr.includes('ALTERN'))score+=3; else if(pr.includes('COND'))score-=5;
 const active=state.plans.filter(x=>x.enabled&&x.role===p.r); score+=active.reduce((a,x)=>a+(+x.weight||0),0)*1.5; return score;
}
function alternativesAvailable(p){return PLAYERS.filter(x=>x.r===p.r&&!state.taken.includes(x.id)&&!state.lost.includes(x.id)&&!state.otherTaken.includes(x.id)&&x.id!==p.id&&activeGuide(x)>0).sort((a,b)=>(activeGuide(b)||0)-(activeGuide(a)||0)).slice(0,5)}
function minimumReserveAfterPurchase(role){return 0}

function marketInfo(role){
  const rows=(state.log||[]).map(x=>{const p=pbyid(x.id);return p&&p.r===role&&+x.price>0?{p,price:+x.price}:null}).filter(Boolean);
  if(rows.length<3)return {count:rows.length,factor:1,label:'Dati insufficienti'};
  const ratios=rows.map(x=>x.price/Math.max(activeGuide(x.p),1)).filter(Number.isFinite);
  const avg=ratios.reduce((a,b)=>a+b,0)/ratios.length;
  const factor=Math.max(0.92,Math.min(1.08,avg));
  return {count:rows.length,factor,label:factor>1.03?'Asta sopra guida':factor<0.97?'Asta sotto guida':'Asta in linea'};
}

function dynamicCeiling(p,current){
 const guide=activeGuide(p)||1, rem=creditsLeft(), futureMin=futureMinimumExcluding(p.r), slots=remainingSlots(p.r);
 if(slots<=0)return 0;
 // After buying this player, at least one credit per remaining slot in the current role and every future role must survive.
 const hardReserve=futureMin+Math.max(0,slots-1);
 const safeCash=Math.max(0,rem-hardReserve);
 const roleBudget=residualRoleBudget(p.r);
 let cap=Math.min(safeCash,roleBudget,guide);
 const market=marketInfo(p.r); if(market.count>=3) cap*=market.factor;
 // Enabled strategies can justify a controlled premium. The guide remains the main anchor.
 cap += Math.min(guide*0.10, Math.max(0,targetPenalty(p))*0.7);
 // Competitive league: small pressure, never enough to override budget protection.
 cap += guide*Math.min(0.05,Math.max(0,(state.teams-8)*0.012));
 const ex=expertInfo(p); if(ex){ const premium=ex.rank<=EXPERT_TOP[p.r]?0.06:ex.rank<=15?0.03:0; cap += guide*premium; }
 cap=Math.min(cap,safeCash);
 return Math.max(1,Math.floor(cap));
}
function adviceData(p,current){
 const c=+current||0,guide=activeGuide(p)||1,cap=dynamicCeiling(p,current);let alt=alternativesAvailable(p), reasons=[];
 if(!c)return {cls:'warn',head:'⌨️ INSERISCI IL PREZZO',text:'Inserisci il prezzo che sta raggiungendo prima che venga assegnato.',cap};
 if(c>cap)return {cls:'stop',head:'🔴 LASCIA',text:'Il prezzo supera la soglia sostenibile ora: considera budget residuo, slot, strategia e i vincoli delle fasi future.',cap};
 if(c<=guide*.85)return {cls:'go',head:'🟢 RILANCIA',text:'Prezzo molto sotto il costo guida e dentro il budget sostenibile.',cap};
 if(c<=guide*1.02)return {cls:'go',head:'🟢 ANCORA OK',text:'Prezzo in linea con il riferimento. Puoi continuare senza compromettere la rosa.',cap};
 reasons.push('prezzo sopra la guida'); if(remainingSlots(p.r)<=2)reasons.push('pochi slot rimasti'); if(alt.length<=2)reasons.push('poche alternative');
 return {cls:'warn',head:'🟡 ATTENZIONE',text:'Puoi continuare solo se la strategia lo giustifica. '+reasons.join(', ')+'.',cap};
}
function why(p,current){const guide=activeGuide(p)||1,c=+current||0,cap=dynamicCeiling(p,current),alts=alternativesAvailable(p);return `<div class="three"><div class="kpi"><span>Riferimento attivo</span><b>${money(guide)}</b><div class="small">${sourceLabel(p.costSource)} · scelta specifica di questo giocatore · ${expertLabel(p)} · FVM ${p.fvm} → ${money(p.fvm500)}/500</div></div><div class="kpi"><span>Prezzo attuale</span><b>${c?money(c):'—'}</b><div class="small">${c?money(c/500*100)+'% del budget':''}</div></div><div class="kpi"><span>Soglia consigliata</span><b>${money(cap)}</b><div class="small">non è il tuo massimale</div></div></div><div class="small" style="margin-top:8px"><b>Perché:</b> budget ruolo residuo ${money(roleRemainingBudget(p.r))}; slot ${remainingSlots(p.r)}; budget future gestito dalle percentuali dinamiche; alternative rilevanti ${alts.length}; andamento asta: ${marketInfo(p.r).label} (${marketInfo(p.r).count} venduti); priorità ${p.priority||'nessuna'}. ${p.note?esc(p.note):''}</div>`}
function renderHeader(){document.getElementById('hCredits').textContent=money(creditsLeft());document.getElementById('hRoster').textContent=state.taken.length+'/25';document.getElementById('hSpent').textContent=money(spentTotal());document.getElementById('hAvail').textContent=PLAYERS.filter(p=>!state.taken.includes(p.id)&&!state.otherTaken.includes(p.id)).length;const ph=currentPhase();document.getElementById('hPhase').textContent=ROLE[ph];const hb=document.getElementById('hPhaseBudget');if(hb)hb.textContent=money(phaseMaxBudget(ph));}
function alerts(){let a=[];for(const r of 'PDCA'){let b=baseBudget(r),s=state.spent[r]||0;if(s>b+0.01)a.push(`<div class="alert orange">🟠 <b>${ROLE[r]}:</b> hai superato di ${money(s-b)} crediti il budget base.</div>`)}return a.join('')}
function marketStats(){const rows=(state.log||[]).map(x=>({p:pbyid(x.id),price:+x.price||0})).filter(x=>x.p&&x.price>0);const out={};for(const r of 'PDCA'){const a=rows.filter(x=>x.p.r===r);let sg=0,sp=0,n=0;for(const x of a){const g=activeGuide(x.p);if(g>0){sg+=g;sp+=x.price;n++;}}out[r]={count:a.length,avg:n?sp/n:0,ratio:n?sp/sg:1};}return out}
function marketSummary(){const m=marketStats();return 'PDCA'.split('').map(r=>{const x=m[r],d=(x.ratio-1)*100;return `<div class="kpi"><span>${ROLE[r]} · mercato</span><b>${x.count?(d>=0?'+':'')+d.toFixed(0)+'%':'—'}</b><div class="small">${x.count} venduti · media ${x.count?money(x.avg):'—'} · vs guida</div></div>`}).join('')}
function remainingByRole(r){return PLAYERS.filter(p=>p.r===r&&!state.taken.includes(p.id)&&!state.otherTaken.includes(p.id))}
function roleAvailabilityCard(r){const a=remainingByRole(r),top=a.filter(p=>expertGroup(p)==='TOP').length,tit=a.filter(p=>expertGroup(p)==='TITOLARI').length;return `<div class="kpi"><span>${ROLE[r]}</span><b>${a.length}</b><div class="small">${top} Top · ${tit} Titolari · ${remainingSlots(r)} slot tuoi</div></div>`}
function renderHome(){let rows='PDCA'.split('').map(r=>`<tr><td>${ROLE[r]}</td><td>${money(state.pct[r])}%</td><td>${money(state.spent[r])}</td><td>${actualPct(r).toFixed(1)}%</td><td>${rebalancePcts()[r].toFixed(1)}%</td><td>${money(roleRemainingBudget(r))}</td><td>${remainingSlots(r)}</td></tr>`).join('');document.getElementById('home').innerHTML=`<div class="card"><div class="title">⚽ Fantacalcio Asta Control</div><div class="small">Strumento pubblico per preparare e gestire la tua asta. Il database di base è condiviso; strategie, massimali, note e stato dell’asta restano personali sul tuo dispositivo.</div><div class="two" style="margin-top:8px">${state.onboarded?`<div class="alert green" style="margin:0">✅ Asta configurata · ${state.emailEnabled?'salvataggio attivo':'salvataggio locale disattivato · email facoltativa'}</div>`:`<button class="btn gold" onclick="showOnboarding()">⚙️ Configura asta</button>`}<button class="btn blue" onclick="goLive()">⚡ Asta Live</button></div></div><div class="card"><div class="title">🧠 Regia asta</div><div class="grid"><div class="kpi"><span>Fase</span><b>${ROLE[currentPhase()]}</b><div class="small">${state.phaseIndex+1}/4</div></div><div class="kpi"><span>Budget massimo fase</span><b>${money(phaseMaxBudget(currentPhase()))}</b><div class="small">${money(phaseAvailableBudget(currentPhase()))} disponibili dopo ${money(state.spent[currentPhase()]||0)} spesi · ${money(state.pct[currentPhase()])}% del budget</div></div></div>${alerts()}</div><div class="card"><div class="title">💰 Budget P / D / C / A</div><table class="table"><tr><th>Ruolo</th><th>Base</th><th>Speso</th><th>% reale</th><th>% residua dinamica</th><th>Budget ora</th><th>Slot</th></tr>${rows}</table><div class="small" style="margin-top:8px">La percentuale dinamica è calcolata sui <b>crediti ancora disponibili</b>: se spendi il 9% in porta invece dell'8%, la quota residua degli altri ruoli si ridistribuisce automaticamente. La somma delle percentuali residue è sempre 100%.</div></div><div class="card"><div class="title">📈 Mercato reale dell'asta</div><div class="grid">${marketSummary()}</div><div class="small" style="margin-top:8px">Confronto tra i prezzi registrati e il riferimento attivo del giocatore. Più giocatori inserisci, più il dato diventa indicativo.</div></div><div class="card"><div class="title">👥 Disponibilità per ruolo</div><div class="grid">${roleAvailabilityCard("P")}${roleAvailabilityCard("D")}${roleAvailabilityCard("C")}${roleAvailabilityCard("A")}</div></div><div class="card"><div class="title">🎯 Obiettivi e piani</div>${state.plans.filter(x=>x.enabled).map(x=>`<div class="plan"><b>${esc(x.name)}</b> <span class="tag gold">${ROLE[x.role]}</span><span class="tag">${esc(x.type)}</span><div class="small">${esc(x.text)}</div></div>`).join('')}</div><div class="card"><div class="title">⚡ Azioni rapide</div><div class="two"><button class="btn gold" onclick="goLive()">Apri Asta Live</button><button class="btn blue" onclick="goStrategy()">Modifica strategia</button></div></div>`}
function goLive(){document.querySelector('[data-v=live]').click()}
function goStrategy(){document.querySelector('[data-v=strategy]').click()}
function setPhase(i){state.phaseIndex=Math.max(0,Math.min(3,+i));save();renderAll()}
function renderLive(){const activePlans=state.plans.filter(x=>x.enabled&&(!x.role||x.role===currentPhase()||x.role==='A'));document.getElementById('live').innerHTML=`<div class="card"><div class="title">⚡ Asta Live — ${ROLE[currentPhase()]}</div><div class="alert green"><b>Prima di iniziare:</b> queste sono le strategie attive per la fase. Il pulsante “Cosa faccio?” le usa insieme a budget, Stima, mercato e prezzo corrente.</div><div class="planline">${activePlans.length?activePlans.map(x=>`<span class="tag gold">${esc(x.name)}</span>`).join(' '):'<span class="small">Nessuna strategia attiva per questa fase.</span>'}</div><div class="controls" style="margin-top:8px"><input id="liveSearch" autocomplete="off" placeholder="Cerca giocatore..."><select id="liveRole"><option value="">Tutti i ruoli</option><option value="P">Portieri</option><option value="D">Difensori</option><option value="C">Centrocampisti</option><option value="A">Attaccanti</option></select><button class="btn" onclick="panic()">🚨 Cosa faccio?</button></div><div id="liveResults"></div></div>`;document.getElementById('liveSearch').addEventListener('input',renderLiveResults);document.getElementById('liveRole').addEventListener('change',renderLiveResults);renderLiveResults()}
function renderLiveResults(){const search=document.getElementById('liveSearch'),role=document.getElementById('liveRole');let q=(search?.value||'').trim().toLowerCase(),r=role?.value||'';let arr=PLAYERS.filter(p=>(!q||p.n.toLowerCase().includes(q)||p.team.toLowerCase().includes(q))&&(!r||p.r===r)&&!state.taken.includes(p.id)&&!state.otherTaken.includes(p.id)).slice(0,30);document.getElementById('liveResults').innerHTML=arr.length?arr.map(p=>`<div class="player"><div class="role">${p.r}</div><div><div class="pname">${esc(p.n)}</div><div class="meta">${esc(p.team)} · Riferimento attivo <b>${money(activeGuide(p))}</b> · Quot. ${p.quote} · FVM ${p.fvm}</div><div class="tags">${p.target?`<span class="tag gold">🎯 ${esc(p.priority||'OBIETTIVO')}</span>`:''}<span class="tag ${p.costSource==='PERSONALE'?'green':'blue'}">${sourceLabel(p.costSource)}</span>${state.lost.includes(p.id)?'<span class="tag red">PERSO</span>':''}</div></div><div class="price"><button class="btn gold" onclick="openLive(${p.id})">Apri</button></div></div>`).join(''):'<div class="small" style="margin-top:8px">Nessun risultato.</div>'}
function openLive(id){let p=pbyid(id);state.live=id;save();renderLiveDetail(p)}
function renderLiveDetail(p){document.getElementById('live').innerHTML=`<div class="livebox"><div class="pname">${esc(p.n)} · ${esc(p.team)} · ${ROLE[p.r]}</div><div class="small">Quotazione ${p.quote} · FVM ${p.fvm} (${money(scaled(p.fvm500))}/${money(state.credits)}) · Costo attivo ${money(activeGuide(p))}/${money(state.credits)} · fonte ${sourceLabel(p.costSource)} per questo giocatore · ${expertLabel(p)} ${expertGroupBadge(p)}</div><div class="bigprice" id="bigNow">—</div><div class="controls"><input id="currentPrice" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="off" enterkeyhint="done" placeholder="Prezzo attuale" value="${state.livePrice??''}" oninput="setLivePrice(this.value);calcAdvice(${p.id})"><button class="btn gold" type="button" onclick="calcAdvice(${p.id})">Analizza</button><button class="btn" type="button" onclick="renderLive()">Cambia</button></div><div id="adviceBox"></div><div class="two" style="margin-top:8px"><button class="btn green" type="button" onclick="take(${p.id})">✓ Acquistato da me</button><button class="btn red" type="button" onclick="otherTake(${p.id})">👤 Acquistato da un altro</button></div></div>`; if(state.livePrice){const n=+state.livePrice;document.getElementById('bigNow').textContent=n?money(n)+' crediti':'—';}}
function setLivePrice(v){const clean=String(v||'').replace(/[^0-9]/g,'');state.livePrice=clean;save();const b=document.getElementById('bigNow');if(b){const n=+clean;b.textContent=n?money(n)+' crediti':'—';}}
function calcAdvice(id){let p=pbyid(id),c=+(document.getElementById('currentPrice')?.value||state.livePrice||0)||0;state.livePrice=String(c||'');document.getElementById('bigNow').textContent=c?money(c)+' crediti':'—';let d=adviceData(p,c);document.getElementById('adviceBox').innerHTML=`<div class="advice ${d.cls}"><div class="headline">${d.head}</div><div style="margin-top:5px">${d.text}</div><div style="margin-top:8px"><b>Soglia consigliata: ${money(d.cap)}</b></div></div>${why(p,c)}<div class="two" style="margin-top:8px"><button class="btn" onclick="editPlayer(${id})">✎ Modifica giocatore</button></div>`}
function take(p){let price=+(document.getElementById('currentPrice')?.value||state.livePrice||0)||0;if(!price)return alert('Inserisci il prezzo pagato.');if(price>creditsLeft())return alert('Crediti insufficienti.');if(!remainingSlots(p.r))return alert('Posti terminati per questo ruolo.');checkpoint();state.taken.push(p.id);state.spent[p.r]=(state.spent[p.r]||0)+price;state.log.unshift({id:p.id,price,status:'PRESO DA ME',time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});state.live=null;state.livePrice='';save();renderAll()}
function otherTake(p){let price=+(document.getElementById('currentPrice')?.value||state.livePrice||0)||0;if(!price)return alert('Inserisci il prezzo a cui è stato preso.');checkpoint();if(!state.otherTaken.includes(p.id))state.otherTaken.push(p.id);state.log.unshift({id:p.id,price,status:'PRESO DA ALTRO',time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});state.live=null;save();renderAll()}
function panic(){const r=currentPhase();const plans=state.plans.filter(x=>x.enabled&&x.role===r);showModal(`<div class="title">🚨 Cosa faccio adesso?</div><div class="small">Prima di analizzare il prezzo, queste sono le strategie attive per la fase <b>${ROLE[r]}</b>.</div><div class="plan">${plans.length?plans.map((x,i)=>`<div style="margin-bottom:7px"><b>${i+1}. ${esc(x.name)}</b><div class="small">${esc(x.text)}</div></div>`).join(''):'<div class="small">Nessuna strategia attiva per questa fase. Puoi aggiungerla in Strategia.</div>'}</div><label style="display:block;margin-top:9px;font-size:10px;color:var(--muted)">Giocatore</label><input id="panicPlayer" type="text" placeholder="Scrivi il nome del giocatore" style="width:100%;margin-top:4px;background:#0a111e;color:white;border:1px solid var(--line);border-radius:9px;padding:9px"><label style="display:block;margin-top:9px;font-size:10px;color:var(--muted)">Prezzo attuale</label><input id="panicPrice" type="number" placeholder="Es. 75" style="width:100%;margin-top:4px;background:#0a111e;color:white;border:1px solid var(--line);border-radius:9px;padding:9px"><button class="btn gold" style="margin-top:10px;width:100%" onclick="panicGoByName()">Analizza</button>`)}
function panicGoByName(){const q=(document.getElementById('panicPlayer')?.value||'').trim().toLowerCase();const c=+document.getElementById('panicPrice').value||0;if(!q)return alert('Scrivi il nome del giocatore.');const matches=PLAYERS.filter(x=>!state.taken.includes(x.id)&&!state.otherTaken.includes(x.id)&&(x.n.toLowerCase().includes(q)||x.team.toLowerCase().includes(q)));if(!matches.length)return alert('Giocatore non trovato.');if(matches.length>1){showModal(`<div class="title">Scegli il giocatore</div>${matches.slice(0,8).map(x=>`<button class="btn" style="width:100%;margin-top:6px;text-align:left" onclick="panicGo(${x.id},${c})">${esc(x.n)} · ${esc(x.team)}</button>`).join('')}`);return;}panicGo(matches[0].id,c)}
function panicGo(id,c){closeModal();state.livePrice=String(c||'');openLive(id);requestAnimationFrame(()=>{const el=document.getElementById('currentPrice');if(el){el.value=String(c||'');}calcAdvice(id)})}
function renderPlayers(){const f=state.playerFilters||{q:'',r:'',s:'',g:''};document.getElementById('players').innerHTML=`<div class="card"><div class="title">☷ Listone completo — ${PLAYERS.length} giocatori</div><div class="controls"><input id="pq" placeholder="Cerca nome o squadra" value="${esc(f.q||'')}"><select id="pr"><option value="">Tutti i ruoli</option><option value="P" ${f.r==='P'?'selected':''}>P</option><option value="D" ${f.r==='D'?'selected':''}>D</option><option value="C" ${f.r==='C'?'selected':''}>C</option><option value="A" ${f.r==='A'?'selected':''}>A</option></select><select id="ps"><option value="" ${!f.s?'selected':''}>Tutti</option><option value="target" ${f.s==='target'?'selected':''}>Miei obiettivi</option><option value="available" ${f.s==='available'?'selected':''}>Disponibili</option><option value="taken" ${f.s==='taken'?'selected':''}>Presi da me</option><option value="other" ${f.s==='other'?'selected':''}>Presi da altri</option></select><select id="pg"><option value="">Gruppo guida: tutti</option><option value="TOP">TOP</option><option value="TITOLARI">TITOLARI</option></select></div><div class="small" style="margin-top:7px">⭐ Fonte attiva = valore usato davvero nell'Asta Live: 📊 Stima (FVM convertito 1000→budget scelto) oppure ✏️ Personale. La fonte è modificabile per ogni giocatore.</div><div id="plist"></div></div>`;document.getElementById('pq').oninput=debouncedPlayerList;document.getElementById('pr').onchange=renderPlayerList;document.getElementById('ps').onchange=renderPlayerList;document.getElementById('pg').onchange=renderPlayerList;renderPlayerList()}
let playerListTimer=null;function debouncedPlayerList(){clearTimeout(playerListTimer);playerListTimer=setTimeout(renderPlayerList,120)}
function renderPlayerList(){const qEl=document.getElementById('pq'),rEl=document.getElementById('pr'),sEl=document.getElementById('ps'),gEl=document.getElementById('pg');let q=(qEl?.value||'').toLowerCase(),r=rEl?.value||'',s=sEl?.value||'',g=gEl?.value||'';state.playerFilters={q,r,s,g};save();let arr=PLAYERS.filter(p=>(!q||p.n.toLowerCase().includes(q)||p.team.toLowerCase().includes(q))&&(!r||p.r===r)&&(!s||(s==='target'&&p.target)||(s==='taken'&&state.taken.includes(p.id))||(s==='other'&&state.otherTaken.includes(p.id))||(s==='available'&&!state.taken.includes(p.id)&&!state.otherTaken.includes(p.id)))&&(!g||expertGroup(p)===g)).slice(0,160);document.getElementById('plist').innerHTML=arr.map(playerCard).join('')+(arr.length===160?'<div class="small">Primi 160 risultati: usa la ricerca.</div>':'')}
function playerCard(p){let status=state.taken.includes(p.id)?'<span class="tag green">PRESO DA ME</span>':state.otherTaken.includes(p.id)?'<span class="tag red">PRESO DA ALTRO</span>':'';return `<div class="player"><div class="role">${p.r}</div><div><div class="pname">${esc(p.n)}</div><div class="meta">${esc(p.team)} · Quot. ${p.quote} · FVM ${p.fvm} · <b>Stima ${money(scaled(p.estimate500))}</b> · ${expertLabel(p)} ${expertGroupBadge(p)}</div><div class="tags"><span class="tag blue">📊 Stima</span>${p.personal500!=null?'<span class="tag green">✏️ Personale '+money(currentPersonal(p))+'</span>':''}${status}</div></div><div class="price"><b>${money(activeGuide(p))}</b><small>riferimento</small><button class="btn" onclick="editPlayer(${p.id})">✎</button></div></div>`}
function editPlayer(id){let p=pbyid(id);showModal(`<div class="title">✎ Modifica ${esc(p.n)}</div><div class="small">${expertLabel(p)} ${expertGroupBadge(p)} · La Stima deriva dal FVM e viene riconvertita automaticamente in base ai crediti della tua asta.</div><div class="editgrid"><div><label>📊 Stima / budget corrente</label><input value="${money(scaled(p.estimate500))}" readonly></div><div><label>✏️ Costo personale / budget corrente</label><input id="ePersonal" type="number" min="0" step="0.1" value="${p.personal500!=null?money(currentPersonal(p)):''}" placeholder="0 = non impostato"></div><div><label>Fonte usata da Asta Live</label><select id="eSource"><option value="STIMA" ${p.costSource!=='PERSONALE'?'selected':''}>📊 Stima</option><option value="PERSONALE" ${p.costSource==='PERSONALE'?'selected':''}>✏️ Personale</option></select></div><div><label>Priorità</label><input id="ePr" value="${esc(p.priority||'')}"></div><div><label>Gruppo guida</label><input value="${esc(expertGroup(p)||'—')}" readonly></div><div class="full"><label>Nota / strategia</label><textarea id="eNote" rows="5">${esc(p.note||'')}</textarea></div><div><label><input id="eTarget" type="checkbox" ${p.target?'checked':''}> È un mio obiettivo</label></div></div><div class="two" style="margin-top:8px"><button class="btn green" onclick="savePlayerEdit(${id})">Salva</button><button class="btn" onclick="closeModal()">Annulla</button></div>`)}
function savePlayerEdit(id){let p=pbyid(id);p.personal500=ePersonal.value===''?null:Math.max(0,(+ePersonal.value||0)/budgetScale());p.costSource=eSource.value;p.priority=ePr.value;p.note=eNote.value;p.target=eTarget.checked;closeModal();save();renderAll()}
function movePlan(i,dir){const j=i+dir;if(j<0||j>=state.plans.length)return;[state.plans[i],state.plans[j]]=[state.plans[j],state.plans[i]];save();renderAll()}
function strategyRows(){return state.plans.map((x,i)=>`<div class="plan"><div><b>${i+1}. ${esc(x.name)}</b> <span class="tag gold">${ROLE[x.role]}</span><span class="tag">${esc(x.type)}</span>${x.enabled?'<span class="tag green">ATTIVA</span>':'<span class="tag red">OFF</span>'}</div><div class="small">Peso ${x.weight??0} · ${esc(x.text)}</div><div class="controls" style="margin-top:6px"><button class="btn" onclick="movePlan(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="btn" onclick="movePlan(${i},1)" ${i===state.plans.length-1?'disabled':''}>↓</button><button class="btn" onclick="editPlan(${i})">✎ Modifica</button><button class="btn" onclick="togglePlan(${i})">${x.enabled?'Disattiva':'Attiva'}</button><button class="btn red" onclick="deletePlan(${i})">Elimina</button></div></div>`).join('')}
function editPlan(i){let x=i<0?{id:'x'+Date.now(),name:'Nuova strategia',role:currentPhase(),type:'priorità',text:'',enabled:true,weight:2}:state.plans[i];showModal(`<div class="title">🎯 ${i<0?'Aggiungi':'Modifica'} strategia</div><div class="editgrid"><div><label>Nome</label><input id="pn" value="${esc(x.name)}"></div><div><label>Ruolo</label><select id="prr">${'PDCA'.split('').map(r=>`<option value="${r}" ${x.role===r?'selected':''}>${ROLE[r]}</option>`).join('')}</select></div><div><label>Tipo</label><select id="ptp">${['priorità','vincolo','blocco','alternativa','condizione','budget','generale'].map(t=>`<option ${x.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label>Peso strategico (0–5)</label><input id="pw" type="number" min="0" max="5" step="0.5" value="${x.weight??2}"></div><div class="full"><label>Strategia / condizione</label><textarea id="pt" rows="6">${esc(x.text)}</textarea></div><label><input id="pe" type="checkbox" ${x.enabled?'checked':''}> Attiva</label></div><div class="two" style="margin-top:8px"><button class="btn green" onclick="savePlan(${i})">Salva</button><button class="btn" onclick="closeModal()">Annulla</button></div>`)}
function savePlan(i){let x={id:i<0?'x'+Date.now():state.plans[i].id,name:pn.value||'Strategia',role:prr.value,type:ptp.value,text:pt.value,enabled:pe.checked,weight:+pw.value||0};if(i<0)state.plans.push(x);else state.plans[i]=x;closeModal();save();renderAll()}
function deletePlan(i){if(confirm('Eliminare definitivamente questa strategia?')){state.plans.splice(i,1);save();renderAll()}}
function emailSettings(){showModal(`<div class="title">📧 Email, salvataggio e aggiornamenti</div><div class="small">L’email è sempre facoltativa. Puoi inserirla ora oppure più avanti: non serve per usare l’app. Quando la aggiungi, da quel momento attivi il salvataggio locale automatico e gli strumenti di backup tra dispositivi. L’indirizzo viene inoltre registrato tramite il modulo del sito per eventuali comunicazioni future, se scegli di riceverle.</div><label style="display:block;margin-top:10px;font-size:10px;color:var(--muted)">Email</label><input id="emailEdit" type="email" value="${esc(state.email||'')}" placeholder="nome@email.it" style="width:100%;margin-top:4px;background:#0a111e;color:white;border:1px solid var(--line);border-radius:9px;padding:9px"><label style="display:block;margin-top:10px;font-size:11px"><input id="updatesEdit" type="checkbox" ${state.emailUpdates?'checked':''}> ✉️ Voglio ricevere eventuali aggiornamenti dell’app</label><div class="small" style="margin-top:5px">Questa casella serve solo per future comunicazioni su nuove versioni, miglioramenti e funzioni.</div><div class="two" style="margin-top:10px"><button class="btn green" onclick="saveEmailSettings()">Salva</button><button class="btn" onclick="closeModal()">Annulla</button></div>`)}
async function saveEmailSettings(){const email=(document.getElementById('emailEdit')?.value||'').trim();if(email&&!/^\S+@\S+\.\S+$/.test(email))return alert('Inserisci un indirizzo email valido.');state.email=email;state.emailEnabled=!!email;state.emailUpdates=!!document.getElementById('updatesEdit')?.checked;let remote=false;if(email)remote=await submitEmailSignup(email,state.emailUpdates);save();closeModal();renderAll();if(email)alert(remote?'Email salvata. Salvataggio locale e strumenti di backup sono attivi.':'Email salvata per questo dispositivo. Il salvataggio locale è attivo; l’archivio email del sito sarà attivo dopo il collegamento del database Cloudflare.')}
function renderStrategy(){let rows='PDCA'.split('').map(r=>`<tr><td>${ROLE[r]}</td><td>${state.pct[r].toFixed(1)}%</td><td>${money(state.spent[r])}</td><td>${actualPct(r).toFixed(1)}%</td><td><b>${rebalancePcts()[r].toFixed(1)}%</b></td><td>${money(roleRemainingBudget(r))}</td></tr>`).join('');document.getElementById('strategy').innerHTML=`<div class="card edit"><div class="title">🎯 Impostazioni asta</div><div class="editgrid"><div><label>Partecipanti</label><input id="sTeams" type="number" min="2" max="30" value="${state.teams}"></div><div><label>Crediti iniziali</label><input id="sCredits" type="number" value="${state.credits}"></div>${'PDCA'.split('').map(r=>`<div><label>${ROLE[r]} % base</label><input id="p${r}" type="number" step="0.1" value="${state.pct[r]}"></div>`).join('')}<div><label>Slot P</label><input id="slP" type="number" value="${state.slots.P}"></div><div><label>Slot D</label><input id="slD" type="number" value="${state.slots.D}"></div><div><label>Slot C</label><input id="slC" type="number" value="${state.slots.C}"></div><div><label>Slot A</label><input id="slA" type="number" value="${state.slots.A}"></div><div class="full"><label><input id="autoRb" type="checkbox" ${state.autoRebalance?'checked':''}> Ribilanciamento intelligente</label><div class="small">Le percentuali base restano tue. Le percentuali residue vengono normalizzate sui crediti rimasti dopo ogni acquisto.</div></div><div class="full"><label>Strategia generale</label><textarea id="sNote" rows="4">${esc(state.notes)}</textarea></div></div><div class="two" style="margin-top:8px"><button class="btn gold" onclick="saveStrategy()">Salva impostazioni</button><button class="btn blue" onclick="phaseSettings()">🔀 Ordine fasi</button></div></div><div class="card"><div class="title">📊 Budget dinamico</div><table class="table"><tr><th>Ruolo</th><th>Base</th><th>Speso</th><th>% reale</th><th>% residua</th><th>Budget ora</th></tr>${rows}</table></div><div class="card"><div class="title">🧩 Strategie e piani — tutti modificabili</div>${strategyRows()}<button class="btn gold" style="margin-top:8px" onclick="editPlan(-1)">＋ Aggiungi strategia</button></div><div class="card"><div class="title">🔄 Gestione fasi</div><div class="pillbar">${state.phaseOrder.map((r,i)=>`<button class="${i===state.phaseIndex?'on':''}" onclick="setPhase(${i})">${i+1}. ${ROLE[r]}</button>`).join('')}</div><div class="small" style="margin-top:8px">Puoi cambiare manualmente la fase se l'asta reale lo richiede.</div></div><div class="card"><div class="title">📱 Come mantenere la stessa asta su PC e telefono</div><div class="small"><b>1.</b> Sul dispositivo dove hai fatto le modifiche premi <b>Esporta backup</b>.<br><b>2.</b> Inviati il file <b>fantacalcio_asta_FINAL_backup.json</b> tramite WhatsApp, email, Drive, ecc.<br><b>3.</b> Sull’altro dispositivo apri il sito e premi <b>Importa backup</b>, poi scegli quel file.<br><b>4.</b> Continua da lì e crea un nuovo backup quando vuoi trasferire gli aggiornamenti sull’altro dispositivo.<br><br>L’email abilita il salvataggio automatico su questo dispositivo e nel tuo spazio/account dell’app; non crea una sincronizzazione automatica dell’intera asta tra dispositivi. Per continuare la stessa asta su un altro dispositivo, usa Esporta backup e poi Importa backup.</div></div><div class="card"><div class="title">📧 Salvataggio e aggiornamenti</div><div class="small">Email: <b>${state.email?esc(state.email):'non inserita'}</b> · Salvataggio: <b>${state.emailEnabled?'ATTIVO':'DISATTIVATO'}</b> · Aggiornamenti: <b>${state.emailUpdates?'ATTIVI':'NO'}</b></div><button class="btn blue" style="margin-top:8px" onclick="emailSettings()">⚙️ Gestisci email</button></div><div class="card"><div class="title">📊 Analisi & backup</div><div class="small">💾 Le modifiche vengono salvate automaticamente su questo dispositivo. Per trasferire la stessa asta tra PC e telefono, usa Esporta backup sul dispositivo attuale e Importa backup sull’altro.</div><div class="two"><button class="btn blue" onclick="exportBackup()">Esporta backup</button><button class="btn blue" onclick="importBackup()">📥 Importa backup</button><button class="btn" onclick="undoLast()">↩ Annulla ultima azione</button><button class="btn red" onclick="resetAll()">Reset asta</button></div></div>`}
function saveStrategy(){let vals={P:+pP.value,D:+pD.value,C:+pC.value,A:+pA.value};if(Object.values(vals).some(v=>v<0)||Math.abs(Object.values(vals).reduce((a,b)=>a+b,0)-100)>.01)return alert('Le percentuali base devono sommare a 100%.');state.teams=Math.max(2,Math.min(30,+sTeams.value||10));state.credits=Math.max(1,+sCredits.value||500);let newSlots={P:+slP.value,D:+slD.value,C:+slC.value,A:+slA.value};if(Object.values(newSlots).some(v=>!Number.isInteger(v)||v<0)||Object.values(newSlots).reduce((a,b)=>a+b,0)!==25)return alert('Gli slot P/D/C/A devono essere interi, non negativi e sommare a 25.');state.pct=vals;state.slots=newSlots;state.autoRebalance=autoRb.checked;state.notes=sNote.value;save();renderAll()}
function phaseSettings(){showModal(`<div class="title">🔀 Ordine delle fasi</div><div class="small">L'asta prevista è P → D → C → A. Puoi modificarla se la tua lega cambia ordine.</div><div class="editgrid">${state.phaseOrder.map((r,i)=>`<div><label>Fase ${i+1}</label><select id="ph${i}">${'PDCA'.split('').map(x=>`<option value="${x}" ${x===r?'selected':''}>${ROLE[x]}</option>`).join('')}</select></div>`).join('')}</div><button class="btn green" style="margin-top:8px" onclick="savePhases()">Salva</button>`)}
function savePhases(){let a=[ph0.value,ph1.value,ph2.value,ph3.value];if(new Set(a).size!==4)return alert('Ogni ruolo deve comparire una volta.');state.phaseOrder=a;state.phaseIndex=0;closeModal();save();renderAll()}
function togglePlan(i){state.plans[i].enabled=!state.plans[i].enabled;save();renderAll()}
function renderLog(){let logs=state.log||[];document.getElementById('log').innerHTML=`<div class="card"><div class="title">📜 Registro asta</div><div class="small">PRESO DA ME modifica budget e rosa. PRESO DA ALTRO elimina l'alternativa e aggiorna il mercato disponibile.</div><table class="table"><tr><th>Ora</th><th>Giocatore</th><th>Esito</th><th>Prezzo</th></tr>${logs.map(x=>{let p=pbyid(x.id);return `<tr><td>${x.time||''}</td><td>${p?esc(p.n):''}</td><td>${x.status}</td><td>${x.price||''}</td></tr>`}).join('')}</table></div>`}
function exportBackup(){if(!state.emailEnabled)return alert('Inserisci un’email in qualsiasi momento da ⚙️ Gestisci email per sbloccare salvataggio e backup. L’email è facoltativa e non serve per usare il sito.');let blob=new Blob([JSON.stringify({version:'PUBLIC-V47',state,players:PLAYERS},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fantacalcio_asta_FINAL_backup.json';a.click()}
function importBackup(){if(!state.emailEnabled)return alert('Inserisci un’email in qualsiasi momento da ⚙️ Gestisci email per sbloccare salvataggio e backup.');showModal(`<div class="title">📥 Importa backup</div><div class="small">Importa un backup creati da questa versione pubblica. Il database ufficiale del listone e le Stime vengono mantenuti; vengono recuperate solo le tue impostazioni personali e lo stato dell'asta.</div><input id="backupFile" type="file" accept="application/json,.json" style="width:100%;margin-top:8px"><div class="two" style="margin-top:8px"><button class="btn green" onclick="doImportBackup()">Importa</button><button class="btn" onclick="closeModal()">Annulla</button></div>`)}
function doImportBackup(){
  const f=document.getElementById('backupFile')?.files?.[0];
  if(!f)return alert('Seleziona un file JSON.');
  const rd=new FileReader();
  rd.onload=()=>{
    try{
      const x=JSON.parse(rd.result);
      if(!x.state||!Array.isArray(x.players))throw Error('Backup non valido');
      checkpoint();
      Object.assign(state,x.state);
      state.credits=+state.credits||500;
      state.teams=+state.teams||10;
      state.onboarded=true;
      state.playerFilters=state.playerFilters||{q:'',r:'',s:'',g:''};
      const old=new Map(x.players.map(p=>[p.id,p]));
      for(const p of PLAYERS){
        const o=old.get(p.id);
        if(o){
          p.target=!!o.target;
          p.max500=o.max500!=null?+o.max500:null;
          p.priority=o.priority||'';
          p.note=o.note||'';
          p.group=o.group||'';
          p.personal500=o.personal500!=null?+o.personal500:null;
          p.costSource=o.costSource==='PERSONALE'?'PERSONALE':'STIMA';
        }
        p.video500=undefined;p.guide500=undefined;p.guidePct=undefined;p.block=undefined;
        p.estimate500=Number.isFinite(+p.fvm)?+p.fvm/2:0;
        p.fvm500=p.estimate500;p.listCost=p.estimate500;p.fvmScale='1000→500';
      }
      save();closeModal();renderAll();
      alert('Backup importato: impostazioni personali e stato asta recuperati. Dati ufficiali del listone mantenuti.');
    }catch(e){alert('Backup non valido o danneggiato: '+e.message)}
  };
  rd.readAsText(f)
}
function resetAll(){
  if(!confirm('Azzerare l’asta e le personalizzazioni? Il listone ufficiale resterà invariato.'))return;
  state={...JSON.parse(JSON.stringify(DEFAULT)),credits:state.credits,teams:state.teams,slots:{...state.slots},pct:{...state.pct},onboarded:true,email:state.email,emailUpdates:state.emailUpdates};
  for(const p of PLAYERS){p.target=false;p.max=null;p.max500=null;p.priority='';p.note='';p.group='';p.personal500=null;p.costSource='STIMA'}
  save();renderAll()
}
function showModal(inner){document.getElementById('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeModal()"><div class="modalbox">${inner}</div></div>`}
function closeModal(){document.getElementById('modal').innerHTML=''}

async function submitEmailSignup(email,updates){try{const r=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,updates})});const data=await r.json().catch(()=>({}));return !!(r.ok&&data.ok)}catch(e){return false}}
function showOnboarding(){showModal(`<div class="title">⚽ Configura la tua asta</div><div class="small">Queste impostazioni influenzano davvero budget, soglie e valori dell’Asta Live. La Stima parte dal FVM convertito e viene riconvertita automaticamente al tuo budget.</div><div class="editgrid" style="margin-top:10px"><div><label>💰 Crediti iniziali</label><input id="obCredits" type="number" min="1" value="500"></div><div><label>👥 Partecipanti</label><input id="obTeams" type="number" min="2" max="30" value="10"></div><div><label>Portieri</label><input id="obP" type="number" min="0" value="3"></div><div><label>Difensori</label><input id="obD" type="number" min="0" value="8"></div><div><label>Centrocampisti</label><input id="obC" type="number" min="0" value="8"></div><div><label>Attaccanti</label><input id="obA" type="number" min="0" value="6"></div><div class="full"><label>📧 Email <span class="muted">(facoltativa)</span></label><input id="obEmail" type="email" placeholder="nome@email.it"><div class="small">L’email è <b>facoltativa</b>. Puoi inserirla anche più avanti da ⚙️ Gestisci email. Se la inserisci, da quel momento abiliti il salvataggio automatico su questo dispositivo e gli strumenti di backup del tuo account/app. Non trasferisce automaticamente l’intera asta su altri dispositivi: per quello puoi usare Esporta backup → Importa backup. Se non la inserisci, puoi comunque usare il sito normalmente.</div></div><div class="full"><label><input id="obUpdates" type="checkbox"> ✉️ Voglio ricevere eventuali aggiornamenti dell’app</label><div class="small">Facoltativo e separato dal salvataggio: serve solo a ricevere comunicazioni future su nuove versioni, miglioramenti o funzioni.</div></div></div><div class="alert green" style="margin-top:10px">📊 Esempio: FVM 200 su base 1000 → Stima 100 su base 500 → se scegli 1000 diventa 200.</div><button class="btn gold" style="width:100%;margin-top:10px" onclick="finishOnboarding()">🚀 Inizia</button>`)}
async function finishOnboarding(){const credits=Math.max(1,+obCredits.value||500),teams=Math.max(2,Math.min(30,+obTeams.value||10));const slots={P:+obP.value||0,D:+obD.value||0,C:+obC.value||0,A:+obA.value||0};if(Object.values(slots).reduce((a,b)=>a+b,0)!==25)return alert('I posti P/D/C/A devono sommare a 25.');state.credits=credits;state.teams=teams;state.slots=slots;state.spent={P:0,D:0,C:0,A:0};state.taken=[];state.otherTaken=[];state.lost=[];state.log=[];state.phaseOrder=['P','D','C','A'];state.phaseIndex=0;state.onboarded=true;state.email=(obEmail.value||'').trim();state.emailEnabled=!!state.email;state.emailUpdates=!!obUpdates.checked;let remote=false;if(state.email)remote=await submitEmailSignup(state.email,state.emailUpdates);save();closeModal();renderAll();if(state.email&&!remote)console.info('Email locale salvata; collega D1 su Cloudflare per archiviarla sul sito.')}

function emailReminder(){if(state.emailEnabled)return;const modal=document.getElementById('modal');if(!modal||modal.innerHTML.trim())return;modal.innerHTML=`<div class="modal email-reminder"><div class="modalbox"><button class="reminder-close" aria-label="Chiudi" onclick="closeModal()">✕</button><div class="title">🔒 Non perdere la tua asta</div><div class="small" style="font-size:12px">Senza email il sito continua a funzionare, ma <b>il salvataggio locale e il backup restano disattivati</b>. Se chiudi o cambi dispositivo potresti perdere le modifiche non esportate.</div><div class="alert orange">📧 Inserisci un’email per attivare il salvataggio su questo dispositivo e i backup. <b>Le notifiche degli aggiornamenti sono facoltative e separate.</b></div><div class="two" style="margin-top:10px"><button class="btn gold" onclick="closeModal();emailSettings()">Inserisci email</button><button class="btn" onclick="closeModal()">Non ora</button></div></div></div>`}function startEmailReminder(){clearInterval(window.__emailReminderTimer);window.__emailReminderTimer=setInterval(()=>{if(!state.emailEnabled)emailReminder();},300000)}
const TUTORIALS={home:{title:'Controllo',text:'Qui vedi budget, fase, mercato e disponibilità. È il cruscotto generale.'},live:{title:'Asta Live',text:'Cerca il giocatore, inserisci il prezzo corrente e leggi subito Rilancia, Attenzione o Lascia. La soglia usa budget, mercato e strategie.'},players:{title:'Listone',text:'Cerca e filtra i giocatori. Con ✎ puoi impostare costo personale, fonte Live, priorità, note e obiettivo.'},strategy:{title:'Strategia',text:'Modifica budget e percentuali, crea strategie e spostale con ↑ ↓ per cambiare l’ordine con cui vengono considerate.'},log:{title:'Registro',text:'Controlla cosa è successo nell’asta: giocatori presi, prezzi e andamento del mercato.'}};
function showTutorial(view,force=false){if(!force&&state.tutorials?.[view])return;const t=TUTORIALS[view];if(!t)return;showModal(`<div class="title">🎮 Mini-guida · ${t.title}</div><div class="small" style="font-size:12px">${t.text}</div><div class="alert green" style="margin-top:10px">💡 Puoi riaprire questa guida quando vuoi con il pulsante <b>ⓘ Guida</b>.</div><button class="btn gold" style="width:100%;margin-top:10px" onclick="closeModal();state.tutorials=state.tutorials||{};state.tutorials['${view}']=true;save()">Ho capito</button>`)}
function addGuideButton(view){const host=document.getElementById(view);if(!host)return;if(host.querySelector('.view-guide'))return;const b=document.createElement('button');b.className='btn view-guide';b.style.margin='0 0 8px 0';b.textContent='ⓘ Guida';b.onclick=()=>showTutorial(view,true);host.prepend(b)}
function renderAll(){renderHeader();renderHome();renderLive();if(state.live){const lp=pbyid(state.live);if(lp)renderLiveDetail(lp)}renderPlayers();renderStrategy();renderLog();['home','live','players','strategy','log'].forEach(addGuideButton);const v=state.activeView||'home';document.querySelectorAll('.view').forEach(x=>x.classList.remove('on'));const el=document.getElementById(v)||document.getElementById('home');el.classList.add('on');document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===el.id))}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.querySelectorAll('.view').forEach(v=>v.classList.remove('on'));document.getElementById(b.dataset.v).classList.add('on');state.activeView=b.dataset.v;save();setTimeout(()=>showTutorial(state.activeView),0)});
window.addEventListener('pagehide',save); window.addEventListener('beforeunload',save);
renderAll();
backupInfo();
startEmailReminder();
// The public landing is the first screen. The app/tutorial opens only after the user chooses to start.

/* ===== V26 LOCAL BACKUP ===== */
function backupInfo(){const el=document.getElementById('saveStatus');if(el)el.textContent=state.emailEnabled?'💾 Salvataggio locale attivo · backup disponibile':'🔒 Salvataggio locale disattivato · email facoltativa · puoi aggiungerla anche dopo';}

function v42Top(e){if(e)e.preventDefault();window.scrollTo({top:0,behavior:'smooth'})}
function v42Scroll(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}
function scrollLanding(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}
function startPublicApp(){
  const land=document.getElementById('publicLanding');
  const app=document.getElementById('appShell');
  if(land)land.style.display='none';
  if(app){app.classList.add('public-started');app.style.removeProperty('display');}
  window.scrollTo({top:0,behavior:'smooth'});
  setTimeout(()=>{ if(!state.onboarded) showOnboarding(); else showTutorial(state.activeView||'home'); },120);
}

function scrollLandingV2(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}

function homeScrollTo(ratio){
  const el=document.querySelector('.exact-home-image');
  if(!el)return;
  const y=el.getBoundingClientRect().top+window.scrollY+el.offsetHeight*ratio;
  window.scrollTo({top:y,behavior:'smooth'});
}

function landingGo(id){const e=document.getElementById(id);if(e)e.scrollIntoView({behavior:'smooth',block:'start'});}
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js?v=46',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{}));}
